use std::io::{Read,Write};use spore_core::cell_feature_loop_v1::pairs;
fn main()->Result<(),Box<dyn std::error::Error>>{let mut input=Vec::new();std::io::stdin().read_to_end(&mut input)?;if input.len()!=160{return Err("expected 5 cases".into())}let mut out=Vec::new();for row in input.chunks_exact(32){let w=|i:usize|u32::from_le_bytes(row[4*i..4*i+4].try_into().unwrap());let a=[w(2),w(3),w(4)];let b=[w(5),w(6),w(7)];let v=pairs([w(0) as i32,w(1) as i32],[&a,&b],true).map_err(|e|format!("{e:?}"))?;if v.len()>9{return Err("case overflow".into())}let mut words=vec![1,2,v.len() as u32];for (i,j) in v{words.extend([i,j])}words.resize(21,0);for x in words{out.extend(x.to_le_bytes())}}std::io::stdout().write_all(&out)?;Ok(())}
